from lib import reflect_adjacent, color_cells, erase_color

def transform(grid):
    """Copy the shape, mirrored across the axis adjacent to its bbox: below if the marker is a plus, sideways if a T."""
    shape = color_cells(grid, 4)
    marker = color_cells(grid, 6)
    rs=[r for r,_ in shape]; cs=[c for _,c in shape]
    if not shape or not marker:
        return [row[:] for row in grid]
    mrs=[r for r,_ in marker]; mcs=[c for _,c in marker]
    # plus marker: cells above and below the bar center -> mirror below; else mirror right
    center_c = sum(mcs)/len(mcs)
    stem_up = any((r,c) in mset for r,c in marker if r < min(mrs)+ (max(mrs)-min(mrs))//2 and c==mcs[len(mcs)//2]) if False else None
    row_counts={r: sum(1 for rr,_ in marker if rr==r) for r in mrs}
    col_counts={c: sum(1 for _,cc in marker if cc==c) for c in mcs}
    bar_row=max(row_counts, key=row_counts.get)
    bar_col=max(col_counts, key=col_counts.get)
    above=any(r<bar_row for r,c in marker if c==bar_col)
    below=any(r>bar_row for r,c in marker if c==bar_col)
    left =any(c<bar_col for r,c in marker if r==bar_row)
    right=any(c>bar_col for r,c in marker if r==bar_row)
    dirs=[x for x,a in (('up',above),('down',below),('left',left),('right',right)) if a]
    if 'up' in dirs and 'down' in dirs:
        copy_dir='down'          # plus marker: mirror below
    else:
        rot={'up':'left','left':'down','down':'right','right':'up'}  # stem rotated 90 deg CCW
        copy_dir=rot[dirs[0]]
    if copy_dir=='down':   out=reflect_adjacent(grid, shape, max(rs)+0.5, horizontal=False)
    elif copy_dir=='up':   out=reflect_adjacent(grid, shape, min(rs)-0.5, horizontal=False)
    elif copy_dir=='right':out=reflect_adjacent(grid, shape, max(cs)+0.5, horizontal=True)
    else:                  out=reflect_adjacent(grid, shape, min(cs)-0.5, horizontal=True)
    return erase_color(out, 6)

def reflect_adjacent(grid, cells, axis, horizontal):
    """Return grid with cells also reflected across the axis immediately adjacent to the shape's bbox (horizontal=True mirrors across vertical axis 2*axis-c; else across horizontal axis 2*axis-r)."""
    out=[row[:] for row in grid]
    R,C=len(grid),len(grid[0])
    for r,c in cells:
        if horizontal:
            cc=int(2*axis-c)
            if 0<=cc<C: out[r][cc]=grid[r][c]
        else:
            rr=int(2*axis-r)
            if 0<=rr<R: out[rr][c]=grid[r][c]
    return out

def color_cells(grid, color):
    """Return list of (r,c) cells with the given color."""
    return [(r,c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c]==color]

def erase_color(grid, color):
    """Return a copy of grid with all cells of the given color set to 0."""
    return [[0 if v==color else v for v in row] for row in grid]

